107	impl Reconciler {
108	    pub fn from_text(text: &str) -> Result<Self, String> {
109	        let mut routes = HashMap::new();
110	        let mut builders: HashMap<String, PolicyBuilder> = HashMap::new();
111	        for (index, raw_line) in text.lines().enumerate() {
112	            let line = raw_line.split('#').next().unwrap_or("").trim();
113	            if line.is_empty() {
114	                continue;
115	            }
116	            let (key, value) = line
117	                .split_once('=')
118	                .ok_or_else(|| format!("invalid config line {}", index + 1))?;
119	            let key = key.trim();
120	            let value = value.trim();
121	            if let Some(route) = key.strip_prefix("route.") {
122	                let (policy, generation_text) = value
123	                    .split_once('@')
124	                    .ok_or_else(|| format!("route {} lacks a generation", route))?;
125	                let generation = generation_text
126	                    .parse::<u64>()
127	                    .map_err(|_| format!("route {} has invalid generation", route))?;
128	                routes.insert(route.to_string(), Binding { policy: policy.to_string(), generation });
129	                continue;
130	            }
131	            if let Some(rest) = key.strip_prefix("policy.") {
132	                let (name, field) = rest
133	                    .rsplit_once('.')
134	                    .ok_or_else(|| format!("invalid policy key {}", key))?;
135	                let builder = builders.entry(name.to_string()).or_default();
136	                match field {
137	                    "scope" => builder.scope = Some(value.to_string()),
138	                    "generation" => builder.generation = Some(parse_number(name, field, value)?),
139	                    "schema" => builder.schema = Some(value.to_string()),
140	                    "wire_format" => builder.wire_format = Some(value.to_string()),
141	                    "REVERSAL_HORIZON" => builder.reversal_horizon = Some(parse_number(name, field, value)?),
142	                    "checkpoint_mode" => builder.checkpoint_mode = Some(value.to_string()),
143	                    _ => return Err(format!("unknown policy field {}", field)),
144	                }
145	                continue;
146	            }
147	            if key.starts_with("diagnostic.") {
148	                continue;
149	            }
150	            return Err(format!("unknown config key {}", key));
151	        }
152	
153	        let mut policies = HashMap::new();
154	        for (name, builder) in builders {
155	            let error_name = name.clone();
156	            let missing = |field: &str| format!("policy {} lacks {}", error_name, field);
157	            let policy = Policy {
158	                scope: builder.scope.ok_or_else(|| missing("scope"))?,
159	                generation: builder.generation.ok_or_else(|| missing("generation"))?,
160	                schema: builder.schema.ok_or_else(|| missing("schema"))?,
161	                wire_format: builder.wire_format.ok_or_else(|| missing("wire_format"))?,
162	                reversal_horizon: builder.reversal_horizon.ok_or_else(|| missing("REVERSAL_HORIZON"))?,
163	                checkpoint_mode: builder.checkpoint_mode.ok_or_else(|| missing("checkpoint_mode"))?,
164	            };
165	            policies.insert(name, policy);
166	        }
167	        Ok(Self { routes, policies })
168	    }
