170	    fn selected(&self, route: &str, scope: &str) -> Result<(&Binding, &Policy), String> {
171	        let binding = self.routes.get(route).ok_or_else(|| format!("unknown route {}", route))?;
172	        let policy = self.policies.get(&binding.policy)
173	            .ok_or_else(|| format!("unknown policy {}", binding.policy))?;
174	        if policy.generation != binding.generation {
175	            return Err("policy generation mismatch".to_string());
176	        }
177	        if policy.scope != scope {
178	            return Err("policy scope mismatch".to_string());
179	        }
180	        Ok((binding, policy))
181	    }
