183	    pub fn reconcile_one(&self, state_dir: &Path, event: LedgerEvent<'_>) -> Result<ReconcileOutcome, String> {
184	        let (binding, policy) = self.selected("RECONCILE", "reconciliation")?;
185	        fs::create_dir_all(state_dir).map_err(|error| error.to_string())?;
186	        let marker = state_dir.join("reconcile.marker");
187	        let recovered_marker = marker.exists();
188	        fs::write(&marker, b"in-progress\n").map_err(|error| error.to_string())?;
189	        let result = self.reconcile_inner(state_dir, event, binding, policy, recovered_marker);
190	        let _ = fs::remove_file(&marker);
191	        result
192	    }
193	
194	    fn reconcile_inner(
195	        &self,
196	        state_dir: &Path,
197	        event: LedgerEvent<'_>,
198	        binding: &Binding,
199	        policy: &Policy,
200	        recovered_marker: bool,
201	    ) -> Result<ReconcileOutcome, String> {
202	        let mut loaded = load_state(state_dir)?;
203	        if loaded.event_ids.contains(event.id) {
204	            return Ok(outcome(ApplyState::Duplicate, binding, policy, &loaded, recovered_marker));
205	        }
206	        if event.schema != policy.schema || event.wire_format != policy.wire_format {
207	            return Ok(outcome(ApplyState::Rejected, binding, policy, &loaded, recovered_marker));
208	        }
209	        if event.sequence <= loaded.checkpoint {
210	            return Ok(outcome(ApplyState::Rejected, binding, policy, &loaded, recovered_marker));
211	        }
212	
213	        let mut lines = Vec::new();
214	        match event.kind {
215	            EventKind::Charge { amount_cents } => {
216	                if amount_cents > i64::MAX as u64 {
217	                    return Ok(outcome(ApplyState::Rejected, binding, policy, &loaded, recovered_marker));
218	                }
219	                lines.push(format!("C|{}|{}|{}", event.id, event.sequence, amount_cents));
220	                loaded.event_ids.insert(event.id.to_string());
221	                loaded.charges.insert(event.id.to_string(), (event.sequence, amount_cents));
222	                loaded.balance_cents += amount_cents as i64;
223	                loaded.max_sequence = loaded.max_sequence.max(event.sequence);
224	
225	                let pending: Vec<Pending> = loaded.pending.iter()
226	                    .filter(|item| item.target_id == event.id && item.target_sequence == event.sequence)
227	                    .cloned()
228	                    .collect();
229	                for item in pending {
230	                    if !loaded.reversed_targets.contains(event.id) {
231	                        lines.push(format!("T|{}|{}|{}", item.reversal_id, event.id, amount_cents));
232	                        loaded.reversed_targets.insert(event.id.to_string());
233	                        loaded.balance_cents -= amount_cents as i64;
234	                    }
235	                    loaded.pending.retain(|candidate| candidate.reversal_id != item.reversal_id);
236	                }
237	            }
238	            EventKind::Reversal { target_id, target_sequence } => {
239	                if event.sequence < target_sequence
240	                    || event.sequence - target_sequence > policy.reversal_horizon
241	                    || loaded.reversed_targets.contains(target_id)
242	                {
243	                    return Ok(outcome(ApplyState::Rejected, binding, policy, &loaded, recovered_marker));
244	                }
245	                loaded.event_ids.insert(event.id.to_string());
246	                loaded.max_sequence = loaded.max_sequence.max(event.sequence);
247	                if let Some((charge_sequence, amount_cents)) = loaded.charges.get(target_id).copied() {
248	                    if charge_sequence != target_sequence {
249	                        return Ok(outcome(ApplyState::Rejected, binding, policy, &loaded, recovered_marker));
250	                    }
251	                    lines.push(format!("R|{}|{}|{}|{}|{}", event.id, event.sequence,
252	                                       target_id, target_sequence, amount_cents));
253	                    loaded.reversed_targets.insert(target_id.to_string());
254	                    loaded.balance_cents -= amount_cents as i64;
255	                } else {
256	                    lines.push(format!("P|{}|{}|{}|{}", event.id, event.sequence,
257	                                       target_id, target_sequence));
258	                    loaded.pending.push(Pending {
259	                        reversal_id: event.id.to_string(),
260	                        target_id: target_id.to_string(),
261	                        target_sequence,
262	                    });
263	                }
264	            }
265	        }
266	
267	        append_lines(&state_dir.join("ledger.log"), &lines)?;
268	        loaded.journal_entries += lines.len();
269	        loaded.checkpoint = checkpoint_for(policy, &loaded)?;
270	        atomic_write(&state_dir.join("checkpoint.state"), format!("{}\n", loaded.checkpoint).as_bytes())?;
271	        atomic_write(&state_dir.join("balance.state"), format!("{}\n", loaded.balance_cents).as_bytes())?;
272	        Ok(outcome(ApplyState::Applied, binding, policy, &loaded, recovered_marker))
273	    }
