296	fn load_state(state_dir: &Path) -> Result<Loaded, String> {
297	    let mut loaded = Loaded::default();
298	    let journal = state_dir.join("ledger.log");
299	    if journal.is_file() {
300	        let text = fs::read_to_string(&journal).map_err(|error| error.to_string())?;
301	        for line in text.lines() {
302	            let fields: Vec<&str> = line.split('|').collect();
303	            loaded.journal_entries += 1;
304	            match fields.as_slice() {
305	                ["C", id, sequence, amount] => {
306	                    let sequence = sequence.parse::<u64>().map_err(|_| "invalid charge sequence".to_string())?;
307	                    let amount = amount.parse::<u64>().map_err(|_| "invalid charge amount".to_string())?;
308	                    loaded.event_ids.insert((*id).to_string());
309	                    loaded.charges.insert((*id).to_string(), (sequence, amount));
310	                    loaded.balance_cents += amount as i64;
311	                    loaded.max_sequence = loaded.max_sequence.max(sequence);
312	                }
313	                ["P", id, sequence, target, target_sequence] => {
314	                    let sequence = sequence.parse::<u64>().map_err(|_| "invalid reversal sequence".to_string())?;
315	                    let target_sequence = target_sequence.parse::<u64>().map_err(|_| "invalid target sequence".to_string())?;
316	                    loaded.event_ids.insert((*id).to_string());
317	                    loaded.pending.push(Pending { reversal_id: (*id).to_string(),
318	                                                  target_id: (*target).to_string(), target_sequence });
319	                    loaded.max_sequence = loaded.max_sequence.max(sequence);
320	                }
321	                ["R", id, sequence, target, target_sequence, amount] => {
322	                    let sequence = sequence.parse::<u64>().map_err(|_| "invalid reversal sequence".to_string())?;
323	                    let _ = target_sequence.parse::<u64>().map_err(|_| "invalid target sequence".to_string())?;
324	                    let amount = amount.parse::<u64>().map_err(|_| "invalid reversal amount".to_string())?;
325	                    loaded.event_ids.insert((*id).to_string());
326	                    loaded.reversed_targets.insert((*target).to_string());
327	                    loaded.balance_cents -= amount as i64;
328	                    loaded.max_sequence = loaded.max_sequence.max(sequence);
329	                }
330	                ["T", reversal_id, target, amount] => {
331	                    let amount = amount.parse::<u64>().map_err(|_| "invalid tombstone amount".to_string())?;
332	                    loaded.reversed_targets.insert((*target).to_string());
333	                    loaded.pending.retain(|item| item.reversal_id != *reversal_id);
334	                    loaded.balance_cents -= amount as i64;
335	                }
336	                _ => return Err("invalid append-only journal entry".to_string()),
337	            }
338	        }
339	    }
340	    let checkpoint = state_dir.join("checkpoint.state");
341	    if checkpoint.is_file() {
342	        loaded.checkpoint = fs::read_to_string(checkpoint)
343	            .map_err(|error| error.to_string())?
344	            .trim()
345	            .parse::<u64>()
346	            .map_err(|_| "invalid checkpoint".to_string())?;
347	    }
348	    Ok(loaded)
349	}
