351	fn checkpoint_for(policy: &Policy, loaded: &Loaded) -> Result<u64, String> {
352	    match policy.checkpoint_mode.as_str() {
353	        "MAX_SEEN" => Ok(loaded.max_sequence),
354	        "PIN_PENDING" => {
355	            let pin = loaded.pending.iter().map(|item| item.target_sequence.saturating_sub(1)).min();
356	            Ok(pin.map(|value| value.min(loaded.max_sequence)).unwrap_or(loaded.max_sequence))
357	        }
358	        "READ_ONLY" => Ok(loaded.checkpoint),
359	        _ => Err("unknown checkpoint mode".to_string()),
360	    }
361	}
