363	fn append_lines(path: &Path, lines: &[String]) -> Result<(), String> {
364	    let mut file = OpenOptions::new().create(true).append(true).open(path)
365	        .map_err(|error| error.to_string())?;
366	    for line in lines {
367	        file.write_all(line.as_bytes()).map_err(|error| error.to_string())?;
368	        file.write_all(b"\n").map_err(|error| error.to_string())?;
369	    }
370	    file.sync_all().map_err(|error| error.to_string())
371	}
