373	fn atomic_write(path: &Path, bytes: &[u8]) -> Result<(), String> {
374	    let name = path.file_name().and_then(|value| value.to_str())
375	        .ok_or_else(|| "state path must have a UTF-8 file name".to_string())?;
376	    let temporary = path.with_file_name(format!(".{}.{}.part", name, std::process::id()));
377	    let result = (|| -> Result<(), String> {
378	        let mut file = OpenOptions::new().write(true).create_new(true).open(&temporary)
379	            .map_err(|error| error.to_string())?;
380	        file.write_all(bytes).map_err(|error| error.to_string())?;
381	        file.sync_all().map_err(|error| error.to_string())?;
382	        fs::rename(&temporary, path).map_err(|error| error.to_string())
383	    })();
384	    if result.is_err() {
385	        let _ = fs::remove_file(&temporary);
386	    }
387	    result
388	}
